  <section class="readiness-section" id="exceptions"><div class="readiness-section-heading"><h2>Needs attention</h2><a class="wbtn" href="<?=url('/write/operations')?>">Review Operations</a></div><div class="readiness-grid"><?php foreach($exceptions as $exception):?><article class="readiness-card"><h3><?=e($exception['label'])?></h3><p class="readiness-summary"><?=intval($exception['count'])?></p><a href="<?=e($exception['url'])?>">Review details →</a></article><?php endforeach;?></div><p class="readiness-small">Counts reflect saved application state. An unknown publishing outcome needs a remote-account check; accepted email and indexing requests do not prove inbox delivery or search visibility.</p></section>
  <section class="readiness-section" id="notifications"><h2>IndexNow notifications</h2><p>Notify participating search engines when canonical public content is added, changed or removed. Google indexing is managed separately through discovery, sitemaps and Search Console.</p>
    <p><strong>Writer permission:</strong> <?=$settings['enabled']?'Enabled':'Paused'?> · <strong>Environment gate:</strong> <?=$settings['environment_enabled']?'Enabled':'Paused'?> · <strong>Worker:</strong> <?=app_config('worker_enabled',false)?'Enabled':'Paused'?></p>
    <form method="post" action="<?=url('/write/discovery/indexnow')?>"><?=csrf_field()?><p><label><input type="checkbox" name="enabled" value="1" <?=$settings['enabled']?'checked':''?>> Allow IndexNow notifications for this site</label></p><p><label><input type="checkbox" name="rotate" value="1"> Replace the current ownership key</label></p><button class="wbtn" type="submit">Save notification preferences</button></form>
    <?php if($settings['enabled'] && $settings['key']!==''):?><p>Ownership proof: <a href="<?=e(url('/'.$settings['key'].'.txt'))?>" target="_blank" rel="noopener noreferrer">Open this site’s key file</a>. Opening the file does not prove a search engine has validated it.</p><?php endif;?>
    <form method="post" action="<?=url('/write/discovery/reconcile')?>"><?=csrf_field()?><button class="wbtn" type="submit">Check public URL changes</button></form><p class="readiness-small">This check only updates the local queue. The authenticated CLI worker sends notifications when all gates are enabled in production. Scheduled content enters the inventory only after its publication time.</p>
    <?php if($notifications):?><div class="readiness-table-wrap"><table><thead><tr><th scope="col">Notification</th><th scope="col">Public URL</th><th scope="col">State</th><th scope="col">Last receipt</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($notifications as $notification):?><tr><td>#<?=intval($notification['id'])?><span class="readiness-small"><?=e($notification['event_type'])?></span></td><td><?=e($notification['canonical_url'])?></td><td><?=e(ucwords(str_replace('_',' ',$notification['status'])))?><span class="readiness-small"><?=intval($notification['attempt_count'])?> attempts<?php if($notification['error_code']):?> · <?=e(str_replace('_',' ',$notification['error_code']))?><?php endif;?></span></td><td><?php if($notification['last_http_status']):?>HTTP <?=intval($notification['last_http_status'])?><?php else:?>No HTTP receipt<?php endif;?><?php if($notification['attempted_at']):?><span class="readiness-small"><?=e($notification['attempted_at'])?> UTC</span><?php endif;?></td><td><?php if(in_array($notification['status'],['rejected','verification_pending'],true)):?><form method="post" action="<?=url('/write/discovery/retry')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=intval($notification['id'])?>"><button class="wbtn" type="submit">Queue recheck</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No public URL notifications have been queued.</p><?php endif;?>
    <?php if($pagination['pages']>1):?><nav class="readiness-nav" aria-label="Notification pages"><?php if($pagination['previous']):?><a rel="prev" href="<?=e(url($pagination['previous']).'#notifications')?>">← Previous</a><?php endif;?><span>Page <?=intval($pagination['page'])?> of <?=intval($pagination['pages'])?> · <?=intval($pagination['total'])?> notifications</span><?php if($pagination['next']):?><a rel="next" href="<?=e(url($pagination['next']).'#notifications')?>">Next →</a><?php endif;?></nav><?php endif;?>
    <p>HTTP 200 means the notification was received. HTTP 202 means ownership-key validation is pending. Neither means the URL is indexed or appears in search results. A rejected request stays visible until reviewed; temporary failures use delayed retries.</p>
    <details><summary>Latest 20 attempt receipts</summary><?php if($receipts):?><div class="readiness-table-wrap"><table><thead><tr><th>Notification / attempt</th><th>Started UTC</th><th>Finished UTC</th><th>Result</th><th>HTTP</th></tr></thead><tbody><?php foreach($receipts as $receipt):?><tr><td>#<?=intval($receipt['queue_id'])?> / <?=intval($receipt['attempt_number'])?></td><td><?=e($receipt['started_at'])?></td><td><?=e($receipt['finished_at']??'No completed receipt')?></td><td><?=e(str_replace('_',' ',$receipt['result']))?></td><td><?=$receipt['http_status']?intval($receipt['http_status']):'—'?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No attempts are recorded.</p><?php endif;?></details>
